mapper.select:
SELECT record_id, tenant_id, scene, idempotency_key, status, fingerprint,
       resource_type, resource_id, result_summary, error_summary,
       created_time, updated_time, expire_time
  FROM sys_idempotency_record
 WHERE tenant_id = #{tenantId}
   AND scene = #{scene}
   AND idempotency_key = #{idempotencyKey}
 LIMIT 1

mapper.update:
UPDATE sys_idempotency_record
   SET status = #{toStatus},
       error_summary = #{errorSummary},
       updated_time = NOW()
 WHERE record_id = #{recordId}
   AND status = #{fromStatus}
